mapper.select:
SELECT * FROM integration_outbox
WHERE tenant_id = #{tenantId} AND provider = #{provider}
  AND binding_id = #{bindingId} AND operation_key = #{operationKey}
LIMIT 1

SELECT * FROM integration_outbox
WHERE provider = #{provider}
  AND (status = 'PENDING' OR (status = 'FAILED' AND next_retry_at <= NOW(3)))
ORDER BY id ASC LIMIT #{limit}

SELECT * FROM integration_outbox
WHERE status = 'PENDING' OR (status = 'FAILED' AND next_retry_at <= NOW(3))
ORDER BY id ASC LIMIT #{limit}

SELECT * FROM integration_outbox
WHERE provider != #{provider}
  AND (status = 'PENDING' OR (status = 'FAILED' AND next_retry_at <= NOW(3)))
ORDER BY id ASC LIMIT #{limit}

SELECT * FROM integration_outbox
WHERE (status = 'SENDING' OR (status = 'UNKNOWN' AND event_type = 'COMMENT_CREATE'))
  AND gmt_modified <= #{before}
ORDER BY gmt_modified ASC, id ASC LIMIT #{limit}

mapper.update:
UPDATE integration_outbox
SET status = 'UNKNOWN', lock_version = lock_version + 1, next_retry_at = NULL
WHERE id = #{id} AND lock_version = #{expectedLockVersion}
  AND status IN ('SENDING', 'UNKNOWN') AND gmt_modified <= #{before}
